<script setup lang="ts">
import { teacherText } from '~/utils/teacher-language'
definePageMeta({ access: { tenant: true } })
useHead({ title: 'Генерация сценария · Школьные события' })
const route = useRoute(), auth = useAuthStore(), api = useGenerationApi()
const { data, pending, error, pauseReason, refresh } = useGenerationRun(() => String(route.params.id))
const scenario = useSchoolResource(async signal => { const result = await api.scenario(data.value!.scenario_id!, auth.tenant!.school_id, signal, data.value!.id); if (result.scenario_request_id !== data.value?.scenario_request_id) throw new Error('Результат не соответствует запросу генерации.'); return result }, () => [data.value?.id, data.value?.scenario_id, data.value?.status, auth.user?.id], () => data.value?.status === 'completed' && !!data.value.scenario_id)
</script>
<template><div class="generation-page"><header><NuxtLink to="/constructor" class="muted">Конструктор / Подготовка проекта</NuxtLink><h1>{{ data?.status === 'completed' ? 'Сценарий готов к оценке педагогом' : data?.status === 'failed' || data?.status === 'timed_out' ? 'Не удалось подготовить проект' : 'Готовим проект мероприятия' }}</h1><p class="muted">Дождитесь готовности проекта. Затем проверьте содержание и материалы.</p></header><div class="generation-layout"><GenerationState v-if="data" :run="data" :pending="pending" :read-error="error ? teacherText(error.message) : undefined" :pause-reason="pauseReason" @refresh="refresh" /><UiCard v-else><UiState v-if="pending" kind="loading" title="Читаем состояние генерации" /><UiState v-else kind="error" title="Состояние недоступно" :description="error?.message"><UiButton @click="refresh">Повторить чтение</UiButton></UiState></UiCard><aside class="generation-context"><UiCard v-if="data"><h2>Ваше мероприятие</h2><NuxtLink :to="`/scenario-requests/${data.scenario_request_id}`">Исходные параметры</NuxtLink><p v-if="scenario.pending.value">Загружаем сохранённый результат…</p><UiAlert v-else-if="scenario.error.value" tone="error">{{ scenario.error.value.message }} <UiButton variant="secondary" @click="scenario.refresh">Повторить чтение сценария</UiButton></UiAlert><p v-else-if="scenario.data.value">{{ scenario.data.value.title }}</p></UiCard><UiAlert tone="warning"><div class="generation-warning"><img src="/icons/fe006/alert.svg" alt="" width="20" height="20"><div><strong>Готовится именно проект</strong><p>После генерации проверьте факты, педагогическую уместность и материалы. ИИ не подтверждает культурные утверждения автоматически.</p></div></div></UiAlert></aside></div></div></template>
